    private val byKeyMap: Map<String, Network> = all.associateBy { it.key }
    private val byOperatorId: Map<Long, Network> =
        all.flatMap { n -> n.operatorIds.map { it to n } }.toMap()

    fun byKey(key: String): Network? = byKeyMap[key]

    /** Keys this catalog used to give a network, mapped to the current one (see [currentKey]). */
    private val renamedKeys: Map<String, String> = mapOf("ewe" to "ewe-go", "blink-charging-uk" to "blink-charging")

    fun currentKey(storedKey: String): String = renamedKeys[storedKey] ?: storedKey

    fun selection(keys: Set<String>): List<Network> = all.filter { it.key in keys }

    /** The network a site belongs to: by OCM operator id first, else by folded keyword. */
    fun resolve(site: ChargeSite): String? {
        site.operatorId?.let { id -> byOperatorId[id]?.let { return it.key } }
        val name = site.operator ?: return null
        val folded = OperatorKey.folded(name)
        return all.firstOrNull { n -> n.nameKeywords.any { containsWord(folded, it) } }?.key
    }

    private fun containsWord(haystack: String, keyword: String): Boolean {
        var from = 0
        while (true) {
            val idx = haystack.indexOf(keyword, from)
            if (idx < 0) return false
            val before = idx == 0 || !haystack[idx - 1].isLetterOrDigit()
            val end = idx + keyword.length
            val after = end >= haystack.length || !haystack[end].isLetterOrDigit()
            if (before && after) return true
            from = idx + 1
        }
    }
}
